592	// waitFor polls until cond is true or the deadline passes; it never sleeps a fixed interval blindly.
593	func oq3WaitFor(timeout time.Duration, cond func() bool) bool {
594		deadline := time.Now().Add(timeout)
595		for time.Now().Before(deadline) {
596			if cond() {
597				return true
598			}
599			time.Sleep(20 * time.Millisecond)
600		}
601		return cond()
602	}
