732	func (d *oq3Daemon) serveChat(w http.ResponseWriter, r *http.Request, body []byte) {
733		var req struct {
734			Model    string `json:"model"`
735			Messages []struct {
736				Role    string `json:"role"`
737				Content string `json:"content"`
738			} `json:"messages"`
739			Admission json.RawMessage `json:"admission"`
740		}
741		_ = json.Unmarshal(body, &req)
742		d.mu.Lock()
743		label := d.label
744		hold := d.holds[label]
745		failStatus := d.fails[label]
746		promptEval := d.promptEval[label]
747		rounds, done := d.toolRounds[label], d.toolsDone[label]
748		d.mu.Unlock()
749	
750		// The response is chosen from the request's shape and the label's declared behaviour, never
751		// from whether the request carries instructions.
752		kind := "reply"
753		n := len(req.Messages)
754		switch {
755		case n > 0 && req.Messages[0].Role == "system" && strings.HasPrefix(req.Messages[0].Content, oq3CompactionSystemPrefix):
756			kind = "summary"
757		case failStatus != 0:
758			kind = "injected-failure"
759		case n > 0 && req.Messages[n-1].Role == "user" && strings.Contains(req.Messages[n-1].Content, oq3ToolTrigger) && rounds > 0 && done == 0:
760			kind = "toolcall"
761		case n > 0 && req.Messages[n-1].Role == "tool" && done > 0 && done < rounds:
762			kind = "toolcall"
763		}
764		d.record(r, body, kind)
765		if kind == "toolcall" {
766			d.mu.Lock()
767			d.toolsDone[label]++
768			call := d.toolsDone[label]
769			d.mu.Unlock()
770			kind = fmt.Sprintf("toolcall-%d", call)
771		}
772		if hold != nil {
773			select {
774			case <-hold:
775			case <-r.Context().Done():
776				return
777			}
778		}
779		if failStatus != 0 {
780			d.mu.Lock()
781			delete(d.fails, label)
782			d.mu.Unlock()
783			w.Header().Set("Content-Type", "application/json")
784			w.WriteHeader(failStatus)
785			io.WriteString(w, `{"error":"oq3 fake daemon: injected failure"}`)
786			d.markCompleted(label)
787			return
788		}
789		defer d.markCompleted(label)
790		model := req.Model
791		if model == "" {
792			model = oq3Model
793		}
794		w.Header().Set("Content-Type", "application/x-ndjson")
795		enc := json.NewEncoder(w)
796		now := "2026-09-26T00:00:00Z"
797		switch {
798		case kind == "summary":
799			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "OQ3-SUMMARY: earlier turns were exchanged."}, "done": false})
800		case strings.HasPrefix(kind, "toolcall-"):
801			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "", "tool_calls": []any{map[string]any{"id": "call_oq3_" + strings.TrimPrefix(kind, "toolcall-"), "function": map[string]any{"name": "read", "arguments": map[string]any{"path": oq3FixtureFile}}}}}, "done": false})
802		default:
803			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": d.nextReply()}, "done": false})
804		}
805		final := map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": ""}, "done": true, "done_reason": "stop", "prompt_eval_count": 10, "eval_count": 3}
806		if promptEval > 0 {
807			final["prompt_eval_count"] = promptEval
808		}
809		if len(req.Admission) > 0 && string(req.Admission) != "null" {
810			// Blueprint §6.3 A9: the final record of an admitted request carries its diagnostics.
811			final["admission"] = map[string]any{"version": 1, "route": "local", "context_length": 32768, "reserve": 4096, "dropped_messages": 0, "context_exhausted": false}
812		}
813		enc.Encode(final)
814	}
