190	// oq3Transform returns the request a correct G1 implementation sends for this delivery, given the
191	// normalised pre-G1 golden for the same step and the expectation. modelSystem is the model-system
192	// text the fake daemon serves for the request's model (desktop base, §5).
193	func oq3Transform(golden any, e oq3Expect, modelSystem func(model string) (string, bool)) (any, error) {
194		exp := oq3DeepCopy(golden)
195		m, ok := exp.(map[string]any)
196		if !ok {
197			return nil, fmt.Errorf("golden is not an object")
198		}
199		if !e.Carrier {
200			delete(m, "admission")
201			return m, nil
202		}
203		text, ok := oq3Texts[e.Text]
204		if !ok {
205			return nil, fmt.Errorf("unknown text %q", e.Text)
206		}
207		carrier := oq3Header(e.Rev, e.Gen) + text
208		msgs, _ := m["messages"].([]any)
209		switch e.Adapter {
210		case "desktop":
211			if len(msgs) > 0 {
212				if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
213					// A pre-G1 desktop request only leads with a system message when MCP servers supplied
214					// instructions; the blueprint does not state how model-system and MCP text are joined
215					// (G1_PERSISTED_INSTRUCTIONS.md:204), so this oracle refuses to guess.
216					return nil, fmt.Errorf("oracle unresolved: desktop golden already leads with a system message (MCP join unspecified)")
217				}
218			}
219			model, _ := m["model"].(string)
220			base, ok := modelSystem(model)
221			if !ok {
222				return nil, fmt.Errorf("no model-system text for %q", model)
223			}
224			content := carrier
225			if base != "" {
226				content = base + "\n\n" + carrier
227			}
228			m["messages"] = append([]any{map[string]any{"role": "system", "content": content}}, msgs...)
229		case "terminal":
230			if len(msgs) > 0 {
231				if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
232					base := oq3Str(first, "content")
233					nf := oq3DeepCopy(first).(map[string]any)
234					if base != "" {
235						nf["content"] = base + "\n\n" + carrier
236					} else {
237						nf["content"] = carrier
238					}
239					msgs[0] = nf
240					m["messages"] = msgs
241					break
242				}
243			}
244			// No built-in base (for example after /system off): the carrier alone leads (§5).
245			m["messages"] = append([]any{map[string]any{"role": "system", "content": carrier}}, msgs...)
246		default:
247			return nil, fmt.Errorf("unknown adapter %q", e.Adapter)
248		}
249		m["admission"] = map[string]any{"version": json.Number("1")}
250		return m, nil
251	}
