423	// terminalStartWithoutCapability starts a session against a daemon without chat.admission.v1 (review
424	// round 2, finding 6; round 3, findings 3 and 4). A12 (blueprint §6.3) and §8 require no
425	// carrier-bearing request and a context_unavailable report naming the daemon's version; nothing
426	// requires the check to wait for a preload, or the session to stay in an idle chat. So the session may
427	// preload and go idle (the unchanged candidate does), or refuse at start-up: exiting, staying in an
428	// idle chat, or staying open elsewhere (for example at a picker). A refusal is recognised only by its
429	// report: the daemon's version and a name for the refusal (oq3RefusalReported). A session that ends at
430	// start-up without that report is a harness failure, never a refusal.
431	func (r *oq3Run) terminalStartWithoutCapability(i int, st oq3Step, preloaded func() bool) {
432		label := oq3Label(r.sc.ID, i, st.Op)
433		reported := func() bool { return oq3RefusalReported(r.term.screen()) }
434		if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() || reported() }) {
435			r.harnessFail("terminal session neither preloaded, reported the missing capability nor exited; screen tail %q", tail(r.term.screen(), 1500))
436		}
437		// A report is often the last thing a refusing process prints before it exits.
438		if reported() && !r.term.hasExited() {
439			oq3WaitFor(2*time.Second, r.term.hasExited)
440		}
441		refused := func(open, idle bool) {
442			r.termRefusedAtStart = true
443			r.termOpenNotIdle = open && !idle
444			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": !open, "idle_chat": idle,
445				"preloaded": preloaded(), "screen_tail": tail(r.term.screen(), 600)})
446		}
447		exitedWithReport := func() {
448			// The output of a process that has just exited may still be draining from the terminal.
449			if !oq3WaitFor(3*time.Second, reported) {
450				r.harnessFail("terminal session exited at start-up without reporting the refusal (the daemon's version %s and context_unavailable or chat.admission.v1); screen tail %q", oq3NoAdmissionVersion, tail(r.term.screen(), 1500))
451			}
452			refused(false, false)
453		}
454		if r.term.hasExited() {
455			exitedWithReport()
456			return
457		}
458		if preloaded() {
459			r.mustPreload(label, "of the session's model")
460		}
461		// Still running: an idle chat is proved as usual; a reported refusal need not reach one.
462		if r.term.idle(15 * time.Second) {
463			if reported() && !preloaded() {
464				refused(true, true)
465				return
466			}
467			r.event(i, st, "done", map[string]any{"session": r.termN, "preloaded": preloaded(), "reported": reported()})
468			return
469		}
470		switch {
471		case r.term.hasExited():
472			exitedWithReport()
473		case reported():
474			if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
475				r.harnessFail("the session reported its refusal but never went quiet; screen tail %q", tail(r.term.screen(), 800))
476			}
477			refused(true, false)
478		default:
479			r.harnessFail("terminal never proved idle after the session started without the capability, and reported no refusal; screen tail %q", tail(r.term.screen(), 800))
480		}
481	}
