483	// oq3RefusedTurnWait is how long a no-dispatch turn waits for any request when the session that
484	// refused at start-up cannot be typed into (it exited, or stayed open outside an idle chat).
485	const oq3RefusedTurnWait = 5 * time.Second
486	
487	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
488		if r.termRefusedAtStart && (r.term.hasExited() || r.termOpenNotIdle) {
489			// The session refused at start-up and cannot be typed into (it exited, or stayed open outside an
490			// idle chat). Nothing is typed; any request under this step within the wait is still captured,
491			// and the step is scored by its class (a refusal held as required).
492			time.Sleep(oq3RefusedTurnWait)
493			r.event(i, st, "no-request", map[string]any{"session": "refused at start-up", "exited": r.term.hasExited(),
494				"requests_under_step": r.d.countLabel(http.MethodPost, "/api/chat", label)})
495			return
496		}
497		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
498		if rounds > 0 {
499			r.d.setToolRounds(label, rounds)
500		}
501		if st.Args["auto_compact"] == "1" {
502			r.d.reportPromptEval(label, 30000)
503		}
504		mark := r.term.rawLen()
505		if st.Args["hold"] == "1" {
506			r.d.hold(label)
507			r.marksLabel["terminal"] = label
508			r.marks["terminal"] = mark
509		}
510		r.term.typeLine(st.Prompt)
511		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
512			// No request reached the daemon: recorded, and scored by the step's class (a missing
513			// required delivery, or a refusal held as required).
514			r.mustIdle("after a turn that sent no request")
515			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
516			return
517		}
518		if st.Args["hold"] == "1" {
519			r.marks["terminal-rounds"] = rounds
520			r.event(i, st, "dispatched-held", nil)
521			return
522		}
523		r.finishTerminalTurn(label, rounds, st.Summarisers, mark)
524		r.event(i, st, "done", nil)
525	}
