527	// finishTerminalTurn approves each declared tool round, then waits until every response under the
528	// label has been fully written by the daemon (review finding 8) and the chat has proved it is idle
529	// (review round 2, finding 5): the daemon finishing and the screen going quiet do not show that the
530	// chat's run has ended.
531	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
532		for k := 0; k < rounds; k++ {
533			approvalMark := mark
534			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
535				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
536			}
537			want := r.d.countLabel("POST", "/api/chat", label) + 1
538			mark = r.term.rawLen()
539			r.term.key("1")
540			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
541				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
542			}
543		}
544		if !oq3WaitFor(30*time.Second, func() bool {
545			n := r.d.countLabel("POST", "/api/chat", label)
546			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
547		}) {
548			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
549				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
550		}
551		r.mustIdle("after the turn completed")
552	}
