554	// mustQuiet waits for the terminal to stop producing output; a timeout is a harness failure, never
555	// a reason to advance (review finding 8). It paces keystrokes into a menu or picker; it is not the
556	// proof that a turn has ended, which is mustIdle.
557	func (r *oq3Run) mustQuiet(when string) {
558		if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
559			r.harnessFail("terminal did not go quiet %s; screen tail %q", when, tail(r.term.screen(), 800))
560		}
561	}
