563	// oq3AckMarker is typed after a command sent while a turn runs; it holds no digit, so an approval prompt
564	// (which answers 1, 2 and 3) could not act on it.
565	const oq3AckMarker = "OQACKZ"
566	
567	// mustIdle requires the chat's own proof that it is idle (oq3Terminal.idle); a timeout is a harness
568	// failure, never a reason to advance (review round 2, finding 5).
569	func (r *oq3Run) mustIdle(when string) {
570		if !r.term.idle(30 * time.Second) {
571			r.harnessFail("terminal never proved idle %s; screen tail %q", when, tail(r.term.screen(), 800))
572		}
573	}
574	
575	func (r *oq3Run) terminalSlash(i int, st oq3Step, label string) {
576		cmd := st.Args["cmd"]
577		mark := r.term.rawLen()
578		if pick := st.Args["pick"]; pick != "" {
579			r.term.typeLine(cmd)
580			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(mark, pick) }) {
581				r.harnessFail("model picker never listed %s; screen tail %q", pick, tail(r.term.screen(), 1500))
582			}
583			// Every wait is checked (review round 2, finding 5); the chat must then prove it is idle, so
584			// the next step cannot start while the switch is still being applied.
585			r.mustQuiet("while the model picker lists " + pick)
586			r.term.key(pick)
587			r.mustQuiet("after filtering the model picker for " + pick)
588			r.term.key("\r")
589			// Switching model starts a preload, which the idle proof cannot see (review round 3, finding 1).
590			r.mustPreload(label, "of "+pick)
591			r.mustIdle("after picking " + pick)
592			r.event(i, st, "done", map[string]any{"picked": pick, "screen_tail": tail(r.term.screen(), 600)})
593			return
594		}
595		r.term.typeLine(cmd)
596		if st.Class == "required-refusal" {
597			// Sent while a held turn runs: nothing on screen can show the refusal, and its effect is judged
598			// by the deliveries that follow (review finding 1; round 2, finding 1). The chat must have
599			// handled the Enter before the response is released, or an approval prompt could take it
600			// (review round 3, finding 2). Keys are handled in order, so a marker typed after the Enter
601			// that reaches the input box proves the Enter was handled while the response was still held,
602			// when no approval prompt can exist. The marker is then cleared.
603			ackMark := r.term.rawLen()
604			r.term.key(oq3AckMarker)
605			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(ackMark, oq3AckMarker) }) {
606				r.harnessFail("the chat did not handle %s while the turn was held (its input box never showed the marker); screen tail %q", cmd, tail(r.term.screen(), 800))
607			}
608			r.term.key("\x15")
609			r.event(i, st, "sent-while-running", map[string]any{"handled_while_held": true})
610			return
611		}
612		if st.Summarisers > 0 {
613			if !oq3WaitFor(30*time.Second, func() bool {
614				return r.d.countSummaries(label) >= st.Summarisers && r.d.completedLabel(label) >= r.d.countLabel("POST", "/api/chat", label)
615			}) {
616				r.mustIdle("after a compaction that did not complete")
617				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
618				return
619			}
620		}
621		r.mustIdle("after " + cmd)
622		unknown := r.term.screenContainsAfter(mark, "Unknown command") || r.term.screenContainsAfter(mark, "usage: ")
623		verdict := "done"
624		switch {
625		case unknown && strings.HasPrefix(cmd, "/instructions"):
626			verdict = "absent"
627		case unknown:
628			// An existing command that printed an error or its usage did not do what the step declares.
629			r.harnessFail("%s was rejected by the terminal; screen tail %q", cmd, tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600))
630		case strings.HasPrefix(cmd, "/instructions"):
631			// No error was printed. The blueprint (§7) names no success output, so the screen cannot
632			// show success; the delivery after this step decides (review finding 1).
633			verdict = "no-error-seen"
634		}
635		r.event(i, st, verdict, map[string]any{"screen_tail": tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600)})
636	}
