1040	// oq3StartTerminalWith starts either a helper (argv nil; helperMode "terminal" is the launch function,
1041	// the other modes are runner controls) or a given program (the built binary for the entry arm) on a
1042	// fresh pseudo-terminal.
1043	func oq3StartTerminalWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, session, model string, argv []string, helperMode string) *oq3Terminal {
1044		master, slave, err := oq3OpenPTY()
1045		if err != nil {
1046			fail("pty: %v", err)
1047		}
1048		var c *exec.Cmd
1049		if argv == nil {
1050			c = oq3HelperCmd(s, d, helperMode, "OQ3_MODEL="+model)
1051		} else {
1052			c = exec.Command(argv[0], argv[1:]...)
1053			c.Dir = s.work
1054			c.Env = s.env(d.srv.URL)
1055		}
1056		c.Stdin, c.Stdout, c.Stderr = slave, slave, slave
1057		c.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Setctty: true, Ctty: 0}
1058		if err := c.Start(); err != nil {
1059			fail("start terminal: %v", err)
1060		}
1061		slave.Close()
1062		p := &oq3Terminal{fail: fail, cmd: c, master: master, exited: make(chan error, 1)}
1063		go p.readLoop(filepath.Join(s.logs, "terminal-"+session+".raw"))
1064		go func() {
1065			err := c.Wait()
1066			p.mu.Lock()
1067			p.gone = true
1068			p.mu.Unlock()
1069			p.exited <- err
1070		}()
1071		return p
1072	}
