1111	// readLoop keeps the transcript and answers the terminal queries a real emulator would answer
1112	// (background colour, foreground colour, cursor position, device attributes).
1113	func (p *oq3Terminal) readLoop(rawPath string) {
1114		f, _ := os.Create(rawPath)
1115		defer func() {
1116			if f != nil {
1117				f.Close()
1118			}
1119		}()
1120		buf := make([]byte, 64*1024)
1121		for {
1122			n, err := p.master.Read(buf)
1123			if n > 0 {
1124				chunk := buf[:n]
1125				if f != nil {
1126					f.Write(chunk)
1127				}
1128				p.mu.Lock()
1129				p.raw.Write(chunk)
1130				p.mu.Unlock()
1131				s := string(chunk)
1132				if strings.Contains(s, "\x1b]11;?") {
1133					p.master.Write([]byte("\x1b]11;rgb:1c1c/1c1c/1c1c\x1b\\"))
1134				}
1135				if strings.Contains(s, "\x1b]10;?") {
1136					p.master.Write([]byte("\x1b]10;rgb:e0e0/e0e0/e0e0\x1b\\"))
1137				}
1138				if strings.Contains(s, "\x1b[6n") {
1139					p.master.Write([]byte("\x1b[1;1R"))
1140				}
1141				if strings.Contains(s, "\x1b[c") || strings.Contains(s, "\x1b[0c") {
1142					p.master.Write([]byte("\x1b[?62;22c"))
1143				}
1144			}
1145			if err != nil {
1146				return
1147			}
1148		}
1149	}
