1163	// quiet waits until the program has produced no output for the given interval.
1164	func (p *oq3Terminal) quiet(interval, timeout time.Duration) bool {
1165		deadline := time.Now().Add(timeout)
1166		last := p.rawLen()
1167		lastChange := time.Now()
1168		for time.Now().Before(deadline) {
1169			time.Sleep(25 * time.Millisecond)
1170			if n := p.rawLen(); n != last {
1171				last, lastChange = n, time.Now()
1172				continue
1173			}
1174			if time.Since(lastChange) >= interval {
1175				return true
1176			}
1177		}
1178		return false
1179	}
