1197	// typeLine types one line into the chat and submits it. ctrl+u first: the chat clears its input line
1198	// (cmd/tui/chat/chat.go KeyCtrlU -> clearInput), so text an earlier step left in the input box (the
1199	// chat keeps an unknown command submitted while a turn runs as input, input.go:100) cannot prefix it.
1200	func (p *oq3Terminal) typeLine(text string) {
1201		if _, err := p.master.Write([]byte("\x15")); err != nil {
1202			p.fail("pty write: %v", err)
1203		}
1204		time.Sleep(60 * time.Millisecond)
1205		if _, err := p.master.Write([]byte(text)); err != nil {
1206			p.fail("pty write: %v", err)
1207		}
1208		time.Sleep(60 * time.Millisecond)
1209		if _, err := p.master.Write([]byte("\r")); err != nil {
1210			p.fail("pty write: %v", err)
1211		}
1212	}
1213	
1214	// oq3IdleProbeText is the status a single ctrl+d sets on an empty input (cmd/tui/chat/chat.go armQuit).
1215	const oq3IdleProbeText = "press ctrl+d again to quit"
1216	
1217	// idle proves that the chat is idle (review round 2, finding 5). With an empty input a single ctrl+d
1218	// only arms quitting and sets a status (chat.go updateCtrlD, armQuit), and the chat draws that status
1219	// only when no turn, compaction or approval prompt is active (render.go renderActionStatusLines,
1220	// notificationLine). It does NOT see a preload: while a model preloads the chat draws no activity line
1221	// (render.go:1449) and still draws notifications, so a step that starts a preload first waits for the
1222	// preload to finish at the daemon (oq3Run.mustPreload; review round 3, finding 1). A turn still
1223	// running overwrites the status when it completes (chat.go chatRunDoneMsg), so the text cannot appear
1224	// before the turn has ended. Each
1225	// attempt clears the input first (ctrl+d arms only on an empty input) and ends with ctrl+u, which
1226	// disarms the quit and returns the status to ready (chat.go disarmQuit), so two ctrl+d are never sent
1227	// without a disarm between them. An open approval prompt ignores both keys (approval.go
1228	// updateApprovalPrompt), so the probe cannot resolve one; it is never sent while a picker is open. The
1229	// daemon's own completion and a quiet screen are not this proof: the chat's run can outlast both.
1230	func (p *oq3Terminal) idle(timeout time.Duration) bool {
1231		deadline := time.Now().Add(timeout)
1232		write := func(s string) bool {
1233			if p.hasExited() {
1234				return false
1235			}
1236			_, err := p.master.Write([]byte(s))
1237			return err == nil
1238		}
1239		for time.Now().Before(deadline) {
1240			if !write("\x15") {
1241				return false
1242			}
1243			time.Sleep(60 * time.Millisecond)
1244			mark := p.rawLen()
1245			if !write("\x04") {
1246				return false
1247			}
1248			seen := oq3WaitFor(1500*time.Millisecond, func() bool { return p.screenContainsAfter(mark, oq3IdleProbeText) })
1249			if !write("\x15") {
1250				return false
1251			}
1252			time.Sleep(60 * time.Millisecond)
1253			if seen {
1254				return true
1255			}
1256		}
1257		return false
1258	}
