1266	func (p *oq3Terminal) waitExit(timeout time.Duration) (error, bool) {
1267		select {
1268		case err := <-p.exited:
1269			p.done = true
1270			return err, true
1271		case <-time.After(timeout):
1272			return nil, false
1273		}
1274	}
