   394	// oq3StringLeaks scans one decoded string: the markers it carries, and, when the string is itself a
   395	// JSON document, the markers inside it after decoding (review round 2, finding 4; round 3, finding 8).
   396	func oq3StringLeaks(s string, depth int) []string {
   397		out := oq3Leaks(s)
   398		if depth < 4 {
   399			if t := strings.TrimSpace(s); (strings.HasPrefix(t, "{") || strings.HasPrefix(t, "[") || strings.HasPrefix(t, `"`)) && json.Valid([]byte(t)) {
   400				inner, _, _ := oq3JSONScan([]byte(t), depth+1)
   401				out = append(out, inner...)
   402			}
   403		}
   404		return out
   405	}
