   867	// oq3EnvelopeLeaks scans what a request carried besides its body (review round 2, finding 4; round 3,
   868	// findings 7 and 8): the decoded path and the raw request target; the query raw, through the partial
   869	// map url.ParseQuery returns even with an error, and component by component with each key and value
   870	// percent-decoded on its own, so one malformed component cannot hide another; and the scan of the
   871	// host, headers and trailers made when the request arrived. Every string goes through the same
   872	// scanner as a body string, JSON inside included.
   873	func oq3EnvelopeLeaks(c oq3Capture) []string {
   874		out := oq3StringLeaks(c.Path, 0)
   875		out = append(out, oq3StringLeaks(c.RequestURI, 0)...)
   876		if c.Query != "" {
   877			out = append(out, oq3StringLeaks(c.Query, 0)...)
   878			q, _ := url.ParseQuery(c.Query)
   879			for k, vs := range q {
   880				out = append(out, oq3StringLeaks(k, 0)...)
   881				for _, v := range vs {
   882					out = append(out, oq3StringLeaks(v, 0)...)
   883				}
   884			}
   885			for _, part := range strings.FieldsFunc(c.Query, func(r rune) bool { return r == '&' || r == ';' }) {
   886				for _, piece := range strings.SplitN(part, "=", 2) {
   887					if u, err := url.QueryUnescape(piece); err == nil {
   888						out = append(out, oq3StringLeaks(u, 0)...)
   889					}
   890					if u, err := url.PathUnescape(piece); err == nil {
   891						out = append(out, oq3StringLeaks(u, 0)...)
   892					}
   893				}
   894			}
   895		}
   896		for _, h := range c.HeaderLeaks {
   897			out = append(out, "envelope "+h)
   898		}
   899		return out
   900	}
